-- Metadati invisibili usati dal motore per gerarchia e sostituzioni.
alter table public.exercises
  add column if not exists stability_profile text not null default 'free',
  add column if not exists axial_load smallint not null default 0,
  add column if not exists unilateral boolean not null default false;

alter table public.exercises
  drop constraint if exists exercises_stability_profile_valid,
  drop constraint if exists exercises_axial_load_valid;

alter table public.exercises
  add constraint exercises_stability_profile_valid
    check (stability_profile in ('supported', 'guided', 'free')),
  add constraint exercises_axial_load_valid check (axial_load between 0 and 3);

-- Correzioni del catalogo storico e backfill dei profili più importanti.
update public.exercises set movement_pattern = 'knee_extension' where id = 'leg_extension';
update public.exercises set movement_pattern = 'calf_raise' where id in ('calf_in_piedi', 'calf_libero', 'calf_manubri', 'calf_seduto');
update public.exercises set exercise_types = array['compound'], roles = array['compound', 'hypertrophy'] where id = 'trazioni_supine';
update public.exercises set exercise_types = array['compound'], roles = array['compound', 'hypertrophy'] where id = 'glute_bridge';
update public.exercises set stability_profile = 'guided' where equipment = 'machine';
update public.exercises set stability_profile = 'supported' where id in ('pulley', 'curl_panca_scott');
update public.exercises set axial_load = 3 where id in ('squat', 'front_squat', 'stacco', 'stacco_rumeno', 'military_press');
update public.exercises set axial_load = 2 where id in ('rematore_bil', 'goblet_squat', 'stacco_rumeno_man');
update public.exercises set unilateral = true where id in ('affondi_man', 'bulgarian_split', 'box_step_up', 'rematore_man');

