    id text, name text, english_name text, primary_muscles text[], secondary_muscles text[],
    equipment text, required_equipment text[], movement_pattern text, roles text[], exercise_types text[],
    min_experience text, technical_complexity smallint, systemic_fatigue smallint, local_fatigue smallint,
    grip_fatigue smallint, default_sets smallint, default_reps text, default_rest smallint,
    stability_profile text, axial_load smallint, unilateral boolean, substitutions text[]
