insert into public.exercises (
  id, name, english_name, primary_muscles, secondary_muscles, equipment, required_equipment,
  movement_pattern, roles, exercise_types, workout_roles, min_experience, technical_complexity,
  systemic_fatigue, local_fatigue, grip_fatigue, cardio_demand, default_sets, default_reps,
  default_rest, instructions, description, category, metcon_safe, warmup_relevant,
  substitutions, stability_profile, axial_load, unilateral, active
)
select
  id, name, english_name, primary_muscles, secondary_muscles, equipment, required_equipment,
  movement_pattern, roles, exercise_types, array['hypertrophy']::text[], min_experience,
  technical_complexity, systemic_fatigue, local_fatigue, grip_fatigue, 1, default_sets,
  default_reps, default_rest,
  'Mantieni una tecnica controllata, usa un range di movimento senza dolore e interrompi la serie prima che la forma peggiori.',
  name || ': variante selezionata per traiettoria, supporto o attrezzatura distinti.',
  equipment, false, false, substitutions, stability_profile, axial_load, unilateral, true
from curated
on conflict (id) do update set
  name = excluded.name,
  english_name = excluded.english_name,
  primary_muscles = excluded.primary_muscles,
  secondary_muscles = excluded.secondary_muscles,
  equipment = excluded.equipment,
  required_equipment = excluded.required_equipment,
  movement_pattern = excluded.movement_pattern,
  roles = excluded.roles,
  exercise_types = excluded.exercise_types,
  substitutions = excluded.substitutions,
  stability_profile = excluded.stability_profile,
  axial_load = excluded.axial_load,
  unilateral = excluded.unilateral,
  active = true;

create index if not exists exercises_replacement_profile_idx
  on public.exercises (movement_pattern, stability_profile, unilateral)
  where active = true;
